function makeNet(){let seed=19;const rand=()=>{seed=(seed*16807)%2147483647;return seed/2147483647*2-1};return {w:Array.from({length:4},()=>[rand(),rand(),rand()]),v:Array.from({length:5},rand),epoch:0,loss:0}}let net=makeNet(),logicTask='XOR';const sigmoid=x=>1/(1+Math.exp(-x));function netPredict(x,y){const h=net.w.map(w=>sigmoid(w[0]*x+w[1]*y+w[2]));return {h,o:sigmoid(h.reduce((s,v,i)=>s+v*net.v[i],net.v[4]))}}function logicTrainingSet(){return [[0,0],[0,1],[1,0],[1,1]].map(([x,y])=>[x,y,logicTask==='AND'?(x&&y?1:0):logicTask==='OR'?(x||y?1:0):(x!==y?1:0)])}function netTrain(n=1,lr=.6){for(let ep=0;ep<n;ep++){let loss=0;for(const [x,y,target] of logicTrainingSet()){const {h,o}=netPredict(x,y);let err=o-target;loss+=-(target*Math.log(Math.max(.00001,o))+(1-target)*Math.log(Math.max(.00001,1-o)));const old=net.v.slice();for(let i=0;i<4;i++){net.v[i]-=lr*err*h[i];const d=err*old[i]*h[i]*(1-h[i]);net.w[i][0]-=lr*d*x;net.w[i][1]-=lr*d*y;net.w[i][2]-=lr*d}net.v[4]-=lr*err}net.loss=loss/4;net.epoch++}}
